// The public errors of the family: what a handler returns, as the Code of a *runtime.PublicError, and a caller tells apart with IsError.
const (
	// ErrorCanceled: The request was canceled.
	ErrorCanceled = "canceled"
	// ErrorConflict: The operation conflicts with the current version or work state.
	ErrorConflict = "conflict"
	// ErrorDeadlineExceeded: The request deadline expired.
	ErrorDeadlineExceeded = "deadline_exceeded"
	// ErrorInternal: An internal server error occurred.
	ErrorInternal = "internal"
	// ErrorInvalidArgument: The operation violates an application input constraint.
	ErrorInvalidArgument = "invalid_argument"
	// ErrorInvalidParams: Operation parameters are invalid.
	ErrorInvalidParams = "invalid_params"
	// ErrorInvalidRequest: The request envelope is invalid.
	ErrorInvalidRequest = "invalid_request"
	// ErrorMethodNotFound: The Workbench operation is unknown.
	ErrorMethodNotFound = "method_not_found"
	// ErrorNotFound: The requested project or work item does not exist.
	ErrorNotFound = "not_found"
	// ErrorUnauthenticated: An authenticated Workbench user is required.
	ErrorUnauthenticated = "unauthenticated"
)

// Errors is every public error code the family declares.
var Errors = []string{ErrorCanceled, ErrorConflict, ErrorDeadlineExceeded, ErrorInternal, ErrorInvalidArgument, ErrorInvalidParams, ErrorInvalidRequest, ErrorMethodNotFound, ErrorNotFound, ErrorUnauthenticated}

// IsError reports whether an error is, or wraps, the family's public error of the code.
func IsError(err error, code string) bool {
	var public *runtime.PublicError
	return errors.As(err, &public) && public.Code == code
}
